from flask.cli import run_command


def test_run_exclude_patterns_option():
    """Test that --exclude-patterns option is parsed correctly."""
    ctx = run_command.make_context("run", ["--exclude-patterns", "*.pyc:*.pyo"])
    assert ctx.params["exclude_patterns"] == ["*.pyc", "*.pyo"]


def test_run_exclude_patterns_default():
    """Test that --exclude-patterns defaults to None."""
    ctx = run_command.make_context("run", [])
